import type { ApprovalPacket, ApprovalList, ApprovalCommandResponse, ApprovalExecutionResponse, Collection, DocumentCollection, DocumentPreview, DocumentRecord, DocumentRevision, HistoryItem, Project, Session, Task } from './types';

const base = '/api/method/';
const core = 'cipher_aec.api.v1.';
const docs = 'cipher_aec.documents.api.';
let csrfToken = '';

export class ApiError extends Error {
  constructor(message: string, public code: string, public status: number, public requestId?: string) {
    super(message);
    this.name = 'ApiError';
  }
}

export async function rpc<T>(method: string, parameters: Record<string, unknown> = {}, write = false, signal?: AbortSignal): Promise<T> {
  const query = new URLSearchParams();
  if (!write) Object.entries(parameters).forEach(([key, value]) => { if (value !== undefined && value !== null) query.set(key, String(value)); });
  let response: Response;
  try {
    response = await fetch(`${base}${method}${query.size ? `?${query}` : ''}`, {
      method: write ? 'POST' : 'GET', credentials: 'same-origin', signal,
      headers: { Accept: 'application/json', ...(write ? { 'Content-Type': 'application/json', 'X-Frappe-CSRF-Token': csrfToken, ...(parameters.operation_id ? { 'Idempotency-Key': String(parameters.operation_id) } : {}) } : {}) },
      ...(write ? { body: JSON.stringify(parameters) } : {}),
    });
  } catch (error) {
    if (error instanceof Error && error.name === 'AbortError') throw error;
    throw new ApiError('The workspace could not be reached. Check your connection and try again.', 'CONNECTION_UNAVAILABLE', 0);
  }
  let body: Record<string, unknown>;
  try { body = await response.json(); }
  catch { throw new ApiError('The workspace returned an unexpected response. Try again or contact your administrator.', 'INVALID_RESPONSE', response.status); }
  const envelope = (body.message ?? body) as { schema?: string; data?: T; request_id?: string; error?: { code?: string; message?: string } };
  if (!response.ok || envelope.error) {
    if (response.status === 401) window.dispatchEvent(new Event('cipher:session-expired'));
    const defaults: Record<number, string> = {
      401: 'Your session has ended. Sign in to continue.', 403: 'You do not have permission for this action.',
      404: 'This record is unavailable or you no longer have access.', 409: 'This action conflicts with a previous request. Refresh the record before continuing.',
      412: 'The source changed. Refresh and review the latest version before saving.',
      429: 'The workspace is busy. Wait a moment and try again.', 503: 'This service is unavailable. Your other work is still available.',
    };
    throw new ApiError(envelope.error?.message || defaults[response.status] || 'The request could not be completed.', envelope.error?.code || `HTTP_${response.status}`, response.status, envelope.request_id);
  }
  if (envelope.schema !== 'cipher.api.v1' || !('data' in envelope)) {
    throw new ApiError('This workspace does not provide the expected Cipher API contract.', 'INVALID_CONTRACT', response.status);
  }
  return envelope.data as T;
}

export const api = {
  async signIn(usr: string, pwd: string) {
    let response: Response;
    try { response = await fetch(`${base}login`, { method: 'POST', credentials: 'same-origin', headers: { Accept: 'application/json', 'Content-Type': 'application/json' }, body: JSON.stringify({ usr, pwd }) }); }
    catch { throw new ApiError('The workspace could not be reached. Try signing in again.', 'CONNECTION_UNAVAILABLE', 0); }
    if (!response.ok) throw new ApiError(response.status === 401 ? 'Check your username and password, then try again.' : response.status === 429 ? 'Too many sign-in attempts. Wait a moment and try again.' : 'Sign-in could not be completed. Try again or contact your administrator.', 'SIGN_IN_FAILED', response.status);
  },
  async signOut() {
    const response = await fetch(`${base}logout`, { method: 'POST', credentials: 'same-origin', headers: { Accept: 'application/json', 'X-Frappe-CSRF-Token': csrfToken } });
    if (!response.ok) throw new ApiError('Sign-out could not be completed. Try again.', 'SIGN_OUT_FAILED', response.status);
    csrfToken = '';
    Object.keys(sessionStorage).filter(key => key.startsWith('cipher.run.')).forEach(key => sessionStorage.removeItem(key));
  },
  async session(signal?: AbortSignal) {
    const data = await rpc<Session>(`${core}session`, {}, false, signal);
    csrfToken = data.csrf_token ?? '';
    return data;
  },
  projects: (company: string, signal?: AbortSignal, cursor?: string) => rpc<Collection<Project>>(`${core}projects`, { company, limit: 50, count_mode: 'exact', cursor }, false, signal),
  project: (company: string, project: string, signal?: AbortSignal) => rpc<Project>(`${core}project`, { company, project }, false, signal),
  tasks: (company: string, project: string, signal?: AbortSignal, cursor?: string) => rpc<Collection<Task>>(`${core}tasks`, { company, project, limit: 50, count_mode: 'exact', cursor }, false, signal),
  history: (company: string, project: string, signal?: AbortSignal, cursor?: string) => rpc<Collection<HistoryItem>>(`${core}history`, { company, project, limit: 50, count_mode: 'exact', cursor }, false, signal),
  createTask: (input: { company: string; project: string; operation_id: string; expected_version: string; subject: string; description?: string }) => rpc<{ task: Task; operation: { id: string; status: string; replayed: boolean }; project_version: string }>(`${core}create_task`, input, true),
  documents: (company: string, project: string, signal?: AbortSignal) => rpc<DocumentCollection>(`${docs}list_documents`, { company, project }, false, signal),
  document: (company: string, document_id: string, signal?: AbortSignal) => rpc<{ document: DocumentRecord; revisions: DocumentRevision[] }>(`${docs}get_document`, { company, document_id }, false, signal),
  preview: (company: string, revision_id: string, page: number, signal?: AbortSignal) => rpc<DocumentPreview>(`${docs}preview_revision`, { company, revision_id, page }, false, signal),
  upload: (input: Record<string, unknown>) => rpc<{ document: DocumentRecord; revision: DocumentRevision; operation: { replayed: boolean } }>(`${docs}upload_document`, input, true),
  approvals: (company: string, project: string, signal?: AbortSignal, cursor?: string) => rpc<ApprovalList>('cipher_aec.api.approvals.list_packets', { company, project, cursor, limit: 50, count_mode: 'exact' }, false, signal),
  approval: (company: string, project: string, packet_id: string, signal?: AbortSignal) => rpc<ApprovalPacket>('cipher_aec.api.approvals.read_packet', { company, project, packet_id }, false, signal),
  requestStatus: (input: { company: string; project: string; status: string; expected_version: string; operation_id: string }) => rpc<ApprovalCommandResponse>('cipher_aec.api.approvals.request_project_status', input, true),
  approvalAction: (action: 'Grant' | 'Reject' | 'execute' | 'withdraw', input: { company: string; project: string; packet_id: string; manifest_hash: string; reason: string; operation_id: string }) => rpc<ApprovalCommandResponse | ApprovalExecutionResponse>(`cipher_aec.api.approvals.${action === 'execute' ? 'execute_packet' : action === 'withdraw' ? 'withdraw_packet' : 'decide_packet'}`, { company: input.company, project: input.project, packet_id: input.packet_id, manifest_hash: input.manifest_hash, operation_id: input.operation_id, ...(action !== 'execute' ? { reason: input.reason } : {}), ...(['Grant', 'Reject'].includes(action) ? { decision: action } : {}) }, true),
  downloadUrl: (company: string, revision_id: string) => `${base}${docs}download_revision?${new URLSearchParams({ company, revision_id })}`,
};

import { useCallback, useEffect, useRef, useState } from 'react';
import { ApiError } from './api/client';

export function useResource<T>(key: string | null, loader: (signal: AbortSignal) => Promise<T>) {
  const loadRef = useRef(loader);
  loadRef.current = loader;
  const [state, setState] = useState<{ key: string | null; data?: T; error?: ApiError; loading: boolean }>({ key, loading: Boolean(key) });
  const [revision, setRevision] = useState(0);
  const refresh = useCallback(() => setRevision(value => value + 1), []);
  useEffect(() => {
    if (!key) { setState({ key, loading: false }); return; }
    const controller = new AbortController();
    setState(previous => ({ key, data: previous.key === key ? previous.data : undefined, loading: true }));
    loadRef.current(controller.signal).then(data => {
      if (!controller.signal.aborted) setState({ key, data, loading: false });
    }).catch(error => {
      if (!controller.signal.aborted) setState({ key, error: error instanceof ApiError ? error : new ApiError('The workspace response could not be read.', 'INVALID_RESPONSE', 0), loading: false });
    });
    return () => controller.abort();
  }, [key, revision]);
  // Never expose a previous company's/project's data during a scope change.
  return state.key === key ? { ...state, refresh } : { key, loading: Boolean(key), data: undefined, error: undefined, refresh };
}

export function useRoute() {
  const [path, setPath] = useState(window.location.pathname + window.location.search);
  useEffect(() => {
    const changed = () => setPath(window.location.pathname + window.location.search);
    window.addEventListener('popstate', changed);
    return () => window.removeEventListener('popstate', changed);
  }, []);
  const navigate = useCallback((next: string) => {
    window.history.pushState({}, '', next);
    setPath(next);
    document.getElementById('main-content')?.focus();
  }, []);
  return { path, navigate };
}

export function date(value?: string | null) {
  if (!value) return 'Not scheduled';
  const parsed = new Date(value.includes('T') ? value : `${value}T12:00:00`);
  return Number.isNaN(parsed.getTime()) ? 'Not scheduled' : new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(parsed);
}
export function human(value: string) { return value.replace(/[_.-]/g, ' ').replace(/^\w/, letter => letter.toUpperCase()); }

import type { ReactNode } from 'react';
import { BusyIndicator, Button, Icon, MessageStrip, ObjectStatus, Title } from '@ui5/webcomponents-react';
import { ApiError } from './api/client';
import { human } from './hooks';

export function Status({ value }: { value: string }) {
  const normalized = value.toLowerCase();
  const state = ['completed', 'complete', 'succeeded', 'saved', 'open', 'active', 'ready', 'executed', 'granted'].includes(normalized) ? 'Positive'
    : ['failed', 'blocked', 'cancelled', 'rejected'].includes(normalized) ? 'Negative'
    : ['waiting_for_review', 'waiting-for-review', 'pending', 'not_scanned', 'quarantined', 'overdue', 'stale', 'expired'].includes(normalized) ? 'Critical'
    : 'Information';
  return <ObjectStatus state={state}>{human(value)}</ObjectStatus>;
}

export function Loading({ label = 'Loading workspace…' }: { label?: string }) {
  return <div className="loading-state" role="status"><BusyIndicator active delay={0} size="M" /><span>{label}</span></div>;
}

export function Failure({ error, onRetry }: { error: ApiError; onRetry?: () => void }) {
  return <div className="failure-state" role="alert">
    <MessageStrip design="Negative" hideCloseButton>{error.message}</MessageStrip>
    <div className="failure-actions">
      {onRetry && <Button icon="refresh" onClick={onRetry}>Try again</Button>}
      {error.status === 401 && <Button design="Emphasized" onClick={() => window.dispatchEvent(new Event('cipher:sign-in'))}>Sign in</Button>}
      {error.requestId && <span className="caption">Reference: {error.requestId}</span>}
    </div>
  </div>;
}

export function Empty({ title, children, icon = 'folder-blank', action }: { title: string; children?: ReactNode; icon?: string; action?: ReactNode }) {
  return <div className="empty-state"><div className="empty-icon"><Icon name={icon} /></div><Title level="H3">{title}</Title>
    {children && <p>{children}</p>}{action}</div>;
}

export function PageHeading({ eyebrow, title, description, actions }: { eyebrow?: string; title: string; description?: string; actions?: ReactNode }) {
  return <header className="page-heading"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}
    <h1>{title}</h1>{description && <p>{description}</p>}</div>{actions && <div className="heading-actions">{actions}</div>}</header>;
}

export function Fact({ label, children, note }: { label: string; children: ReactNode; note?: string }) {
  return <div className="fact"><span className="fact-label">{label}</span><div className="fact-value">{children}</div>{note && <span className="caption">{note}</span>}</div>;
}

export function Pagination({ next, previous, page, total, onNext, onPrevious }: { next?: string | null; previous: boolean; page: number; total?: number | null; onNext: () => void; onPrevious: () => void }) {
  if (!next && !previous) return null;
  return <div className="page-controls" aria-label="Register pagination"><Button icon="navigation-left-arrow" disabled={!previous} onClick={onPrevious}>Previous page</Button><span>Page {page}{total !== undefined && total !== null ? ` · ${total} records` : ''}</span><Button icon="navigation-right-arrow" disabled={!next} onClick={onNext}>Next page</Button></div>;
}

import { useMemo, useState } from 'react';
import { AnalyticalTable, Button, FilterBar, FilterGroupItem, Input, Icon, Link, Option, Select, Title, Toolbar, ToolbarSpacer } from '@ui5/webcomponents-react';
import type { AnalyticalTableColumnDefinition } from '@ui5/webcomponents-react';
import type { Project } from './api/types';
import { date } from './hooks';
import { Empty, Fact, PageHeading, Pagination, Status } from './components';

export default function ProjectRegister({ projects, total, company, search, setSearch, navigate, refresh, pagination }: {
  projects: Project[]; total?: number; company: string; search: string; setSearch: (value: string) => void; navigate: (path: string) => void; refresh: () => void;
  pagination: { next?: string | null; page: number; previous: boolean; onNext: () => void; onPrevious: () => void };
}) {
  const [status, setStatus] = useState('All statuses');
  const statuses = useMemo(() => [...new Set(projects.map(project => project.status))], [projects]);
  const filtered = useMemo(() => projects.filter(project => (!search || `${project.name} ${project.id}`.toLowerCase().includes(search.toLowerCase())) && (status === 'All statuses' || status === project.status)), [projects, search, status]);
  const columns = useMemo<AnalyticalTableColumnDefinition[]>(() => [
    { Header: 'Project', accessor: 'name', minWidth: 260, width: 370, Cell: ({ row }) => { const project = row.original as Project; return <div className="record-cell"><Link onClick={() => navigate(`/projects/${encodeURIComponent(project.id)}`)}>{project.name}</Link><span>{project.id}</span></div>; } },
    { Header: 'Status', accessor: 'status', width: 145, Cell: ({ value }) => <Status value={String(value)} /> },
    { Header: 'Start date', accessor: 'expected_start_date', width: 155, Cell: ({ value }) => <span>{date(value)}</span> },
    { Header: 'Target completion', accessor: 'expected_end_date', width: 170, Cell: ({ value }) => <span>{date(value)}</span> },
    { Header: 'Company', accessor: 'company', minWidth: 180 },
  ], [navigate]);
  const active = projects.filter(project => ['open', 'active', 'in progress'].includes(project.status.toLowerCase())).length;
  const completed = projects.filter(project => ['completed', 'complete'].includes(project.status.toLowerCase())).length;
  return <div className="page register-page">
    <PageHeading eyebrow="PROJECT DELIVERY" title="Projects" description="Your projects, their source documents, and the work ahead." actions={<Button icon="refresh" onClick={refresh}>Refresh</Button>} />
    <section className="summary-strip" aria-label="Loaded project summary">
      <Fact label="Projects in this view" note={total !== undefined && total !== projects.length ? `${total} accessible records · ${projects.length} loaded` : company}>{projects.length}</Fact>
      <Fact label="Active" note="Open and in progress">{active}</Fact>
      <Fact label="Completed" note="Completed projects">{completed}</Fact>
      <div className="context-note"><IconContext /><div><strong>One project context</strong><span>Tasks, documents and Ricky stay connected to the work.</span></div></div>
    </section>
    <section className="surface register-surface" aria-label="Project register">
      <FilterBar hideFilterConfiguration hideToggleFiltersButton showGoOnFB={false} header={<Title level="H2">Project register</Title>}>
        <FilterGroupItem filterKey="search" label="Find a project"><Input accessibleName="Find a project" placeholder="Name or project number" value={search} onInput={event => setSearch(event.currentTarget!.value)} showClearIcon /></FilterGroupItem>
        <FilterGroupItem filterKey="status" label="Status"><Select accessibleName="Project status" onChange={event => setStatus(event.detail.selectedOption.value ?? 'All statuses')}><Option value="All statuses" selected={status === 'All statuses'}>All statuses</Option>{statuses.map(item => <Option key={item} value={item} selected={status === item}>{item}</Option>)}</Select></FilterGroupItem>
      </FilterBar>
      <Toolbar design="Transparent"><span className="result-count">{filtered.length} {filtered.length === 1 ? 'project' : 'projects'}</span><ToolbarSpacer />{(search || status !== 'All statuses') && <Button design="Transparent" onClick={() => { setSearch(''); setStatus('All statuses'); }}>Clear filters</Button>}<span className="caption">Select a project to open its workspace</span></Toolbar>
      {filtered.length ? <AnalyticalTable accessibleName="Projects" columns={columns} data={filtered} sortable rowHeight={62} headerRowHeight={40} minRows={Math.min(filtered.length, 5)} visibleRows={Math.min(Math.max(filtered.length, 3), 10)} scaleWidthMode="Grow" selectionMode="None" />
        : <Empty title={projects.length ? 'No projects match these filters' : 'No projects available'}>{projects.length ? 'Try another name or clear the filters.' : 'Projects you have permission to view will appear here.'}</Empty>}
      <Pagination {...pagination} total={total} />
    </section>
    <div className="page-footnote"><span>Company scope: {company}</span><span>{pagination.next || pagination.previous ? 'Filters apply to this loaded page.' : 'Project access is enforced by your workspace.'}</span></div>
  </div>;
}

function IconContext() { return <div className="context-symbol" aria-hidden="true"><Icon name="chain-link" /></div>; }

import { useState } from 'react';
import { Table, TableHeaderRow, TableHeaderCell, TableRow, TableCell, Bar, Breadcrumbs, BreadcrumbsItem, Button, Dialog, Input, Label, Link, MessageStrip, Title, Toolbar, ToolbarSpacer } from '@ui5/webcomponents-react';
import { api, ApiError } from './api/client';
import type { DocumentRecord } from './api/types';
import { useResource } from './hooks';
import { Empty, Fact, Failure, Loading, PageHeading, Status } from './components';

export function DocumentRegister({ items, navigate }: { items: DocumentRecord[]; navigate: (path: string) => void }) {
  return items.length ? <Table accessibleName="Project documents" overflowMode="Scroll" headerRow={<TableHeaderRow>
    <TableHeaderCell minWidth="17rem">Document</TableHeaderCell><TableHeaderCell width="6.25rem">Revision</TableHeaderCell><TableHeaderCell width="10rem">Text extraction</TableHeaderCell><TableHeaderCell width="8.125rem">File</TableHeaderCell>
  </TableHeaderRow>}>
    {items.map(item => <TableRow key={item.id} rowKey={item.id}>
      <TableCell><div className="record-cell"><Link onClick={() => navigate(`/documents/${encodeURIComponent(item.id)}`)}>{item.title}</Link><span>{item.filename}</span></div></TableCell>
      <TableCell>Rev. {item.revision_number}</TableCell><TableCell><Status value={item.extraction_status} /></TableCell><TableCell>{item.mime_type === 'application/pdf' ? 'PDF' : 'Text'} · {size(item.byte_length)}</TableCell>
    </TableRow>)}
  </Table>
    : <Empty title="No source documents yet" icon="documents">Add a project document to keep the source connected to your work.</Empty>;
}

export function DocumentsPage({ company, projectId, projectName, navigate, canUpload }: { company: string; projectId?: string; projectName?: string; navigate: (path: string) => void; canUpload: boolean }) {
  const documents = useResource(projectId ? `${company}/${projectId}/documents` : null, signal => api.documents(company, projectId!, signal));
  const [uploadOpen, setUploadOpen] = useState(false);
  const [notice, setNotice] = useState('');
  return <div className="page">
    <PageHeading eyebrow="PROJECT SOURCES" title="Documents" description={projectName ? `${projectName} · Working sources and their exact revisions.` : 'Choose a project to work with its documents.'} actions={projectId ? <><Button icon="refresh" onClick={documents.refresh}>Refresh</Button>{canUpload && <Button icon="upload" design="Emphasized" onClick={() => setUploadOpen(true)}>Add document</Button>}</> : undefined} />
    {!projectId ? <div className="surface"><Empty title="Choose a project" icon="folder" action={<Button design="Emphasized" onClick={() => navigate('/projects')}>Open projects</Button>}>Documents are scoped to a project and your current permissions.</Empty></div> : <>
      {notice && <MessageStrip design="Positive" onClose={() => setNotice('')}>{notice}</MessageStrip>}
      <section className="surface"><Toolbar design="Transparent"><Title level="H2">Document register</Title><ToolbarSpacer /><span className="caption">{documents.data?.items.length ?? '—'} documents · PDF and plain text</span></Toolbar>
        {documents.loading ? <Loading label="Loading project documents…" /> : documents.error ? <Failure error={documents.error} onRetry={documents.refresh} /> : <DocumentRegister items={documents.data?.items ?? []} navigate={navigate} />}
      </section>
      <div className="document-policy"><strong>Originals and revisions stay together</strong><p>Opening a document shows its stored source and extraction status. A new upload never changes an issued record.</p></div>
      <UploadDialog open={uploadOpen} company={company} projectId={projectId} onClose={() => setUploadOpen(false)} onSaved={document => { setUploadOpen(false); setNotice(`“${document.title}” was added.`); documents.refresh(); }} />
    </>}
  </div>;
}

export function DocumentPage({ company, documentId, revisionId, initialPage = 1, navigate, askRicky }: { company: string; documentId: string; revisionId?: string; initialPage?: number; navigate: (path: string) => void; askRicky: (projectId: string) => void }) {
  const record = useResource(`${company}/${documentId}`, signal => api.document(company, documentId, signal));
  const [page, setPage] = useState(initialPage);
  const revisionBelongsToDocument = !revisionId || record.data?.revisions.some(revision => revision.id === revisionId);
  const currentRevision = revisionBelongsToDocument ? (revisionId ?? record.data?.document.current_revision) : undefined;
  const preview = useResource(currentRevision ? `${company}/${currentRevision}/${page}` : null, signal => api.preview(company, currentRevision!, page, signal));
  if (record.loading) return <Loading label="Opening source document…" />;
  if (record.error) return <div className="page"><Failure error={record.error} onRetry={record.refresh} /></div>;
  if (!record.data) return null;
  const document = record.data.document;
  if (revisionId && !revisionBelongsToDocument) return <div className="page"><Failure error={new ApiError('This revision is not available for this document.', 'REVISION_UNAVAILABLE', 404)} /><Button onClick={() => navigate(`/documents/${encodeURIComponent(document.id)}`)}>Open current revision</Button></div>;
  const revision = record.data.revisions.find(item => item.id === currentRevision);
  return <div className="page document-page">
    <Breadcrumbs><BreadcrumbsItem onClick={() => navigate('/projects')}>Projects</BreadcrumbsItem><BreadcrumbsItem onClick={() => navigate(`/projects/${encodeURIComponent(document.project)}/documents`)}>Documents</BreadcrumbsItem><BreadcrumbsItem>{document.title}</BreadcrumbsItem></Breadcrumbs>
    <PageHeading eyebrow="SOURCE DOCUMENT" title={document.title} description={revision?.filename ?? document.filename} actions={<><Button icon="da" onClick={() => askRicky(document.project)}>Ask Ricky</Button><Button icon="download" onClick={() => window.open(api.downloadUrl(company, currentRevision!), '_blank', 'noopener,noreferrer')}>Open original</Button></>} />
    <section className="summary-strip document-facts"><Fact label="Revision">Rev. {revision?.revision_number ?? document.revision_number}</Fact><Fact label="Format">{document.mime_type === 'application/pdf' ? 'PDF' : 'Plain text'}</Fact><Fact label="File size">{size(document.byte_length)}</Fact><Fact label="Extraction"><Status value={revision?.extraction_status ?? document.extraction_status} /></Fact></section>
    <div className="document-reader-grid"><section className="surface source-reader" aria-label="Document source preview"><Toolbar design="Transparent"><Title level="H2">Source text</Title><ToolbarSpacer />{preview.data && <span className="caption">Page {page} of {preview.data.page_count}</span>}</Toolbar>
      {preview.loading ? <Loading label="Loading source text…" /> : preview.error ? <div className="reader-body"><Failure error={preview.error} onRetry={preview.refresh} /></div> : preview.data ? <><div className="reader-body"><div className="source-page-heading">{document.title}<span>Revision {revision?.revision_number ?? document.revision_number} · Page {page}</span></div><pre className="source-text">{preview.data.text}</pre></div>{preview.data.page_count > 1 && <div className="page-controls"><Button icon="navigation-left-arrow" disabled={page <= 1} onClick={() => setPage(page - 1)}>Previous</Button><span>Page {page} of {preview.data.page_count}</span><Button icon="navigation-right-arrow" disabled={page >= preview.data.page_count} onClick={() => setPage(page + 1)}>Next</Button></div>}</> : <Empty title="Preview is not available">Open the stored original to review this document.</Empty>}
    </section><aside className="surface source-details"><Title level="H3">Source details</Title><dl><dt>Project</dt><dd><Link onClick={() => navigate(`/projects/${encodeURIComponent(document.project)}`)}>{document.project}</Link></dd><dt>Scan status</dt><dd><Status value={revision?.scan_status ?? document.scan_status} /></dd><dt>Available revisions</dt><dd>{record.data.revisions.length}</dd></dl><p className="caption">Ricky citations link to this exact document revision.</p><details><summary>File integrity</summary><p className="caption">SHA-256</p><code>{revision?.sha256 ?? document.sha256}</code></details></aside></div>
  </div>;
}

function UploadDialog({ open, company, projectId, onClose, onSaved }: { open: boolean; company: string; projectId: string; onClose: () => void; onSaved: (document: DocumentRecord) => void }) {
  const [title, setTitle] = useState('');
  const [file, setFile] = useState<File>();
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<ApiError>();
  const [operationId, setOperationId] = useState(() => crypto.randomUUID());
  const submit = async () => {
    if (!file || !title.trim() || saving) return;
    setSaving(true); setError(undefined);
    try {
      if (file.size > 10 * 1024 * 1024) throw new ApiError('Choose a PDF or text file under 10 MB.', 'FILE_TOO_LARGE', 422);
      const buffer = await file.arrayBuffer();
      const digest = await crypto.subtle.digest('SHA-256', buffer);
      const sha256 = [...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join('');
      const bytes = new Uint8Array(buffer); let binary = '';
      for (let offset = 0; offset < bytes.length; offset += 8192) binary += String.fromCharCode(...bytes.subarray(offset, offset + 8192));
      const result = await api.upload({ company, project: projectId, title: title.trim(), filename: file.name, content_base64: btoa(binary), sha256, byte_length: file.size, operation_id: operationId });
      setTitle(''); setFile(undefined); setOperationId(crypto.randomUUID()); onSaved(result.document);
    } catch (failure) { setError(failure instanceof ApiError ? failure : new ApiError('This file could not be prepared. Choose it again and retry.', 'FILE_READ_FAILED', 0)); }
    finally { setSaving(false); }
  };
  return <Dialog open={open} headerText="Add source document" className="form-dialog" onClose={() => { if (!saving) onClose(); }} footer={<Bar design="Footer" endContent={<><Button design="Emphasized" disabled={!file || !title.trim() || saving} onClick={submit}>{saving ? 'Uploading…' : 'Add document'}</Button><Button disabled={saving} onClick={onClose}>Cancel</Button></>} />}><div className="dialog-form">
    {error && <Failure error={error} />}<Label for="document-title" required>Document title</Label><Input id="document-title" accessibleName="Document title" value={title} onInput={event => { setTitle(event.currentTarget!.value); setOperationId(crypto.randomUUID()); }} />
    <Label for="document-file" required>Source file</Label><input id="document-file" aria-label="Source file" type="file" accept=".pdf,.txt,application/pdf,text/plain" onChange={event => { const next = event.target.files?.[0]; setFile(next); if (next && !title) setTitle(next.name.replace(/\.[^.]+$/, '')); setOperationId(crypto.randomUUID()); }} />
    <p className="caption">PDF or plain text · Up to 10 MB. Files remain unavailable for retrieval until the workspace permits their scan state.</p>
  </div></Dialog>;
}

function size(bytes: number) { return bytes >= 1024 * 1024 ? `${(bytes / (1024 * 1024)).toFixed(1)} MB` : bytes >= 1024 ? `${Math.ceil(bytes / 1024)} KB` : `${bytes} bytes`; }

import { useRef, useState } from 'react';
import { Bar, Button, CheckBox, Dialog, Label, MessageStrip, Option, Select, Table, TableCell, TableHeaderCell, TableHeaderRow, TableRow, TextArea, Title, Toolbar, ToolbarSpacer } from '@ui5/webcomponents-react';
import { api, ApiError } from './api/client';
import type { ApprovalPacket, Project } from './api/types';
import { Empty, Fact, Failure, Loading, Pagination, Status } from './components';
import { useResource } from './hooks';

const timestamp = (value: string) => new Intl.DateTimeFormat('en-US', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value));

export default function Approvals({ project, onEffect }: { project: Project; onEffect: () => void }) {
  const [cursor, setCursor] = useState<string>();
  const [pages, setPages] = useState<(string | undefined)[]>([]);
  const packets = useResource(`${project.company}/${project.id}/approvals/${project.version}/${cursor ?? ''}`, signal => api.approvals(project.company, project.id, signal, cursor));
  const [requestOpen, setRequestOpen] = useState(false);
  const [selected, setSelected] = useState<string>();
  const [notice, setNotice] = useState('');
  return <>
    <Toolbar design="Transparent"><Title level="H2">Approval inbox</Title><ToolbarSpacer /><Button icon="refresh" onClick={packets.refresh}>Refresh approvals</Button>{project.capabilities?.includes('approval.request') && <Button design="Emphasized" disabled={! ['Open', 'On hold'].includes(project.status)} title={['Open', 'On hold'].includes(project.status) ? 'Create an independently reviewed status request' : 'Closed projects cannot be reopened through this approval policy'} onClick={() => setRequestOpen(true)}>Request status change</Button>}</Toolbar>
    {notice && <MessageStrip design="Positive" onClose={() => setNotice('')}>{notice}</MessageStrip>}
    {packets.loading ? <Loading label="Loading approval packets…" /> : packets.error ? <Failure error={packets.error} onRetry={packets.refresh} /> : packets.data?.items.length ? <Table accessibleName="Project approvals" headerRow={<TableHeaderRow><TableHeaderCell minWidth="14rem">Requested change</TableHeaderCell><TableHeaderCell width="9rem">State</TableHeaderCell><TableHeaderCell minWidth="10rem">Requested by</TableHeaderCell><TableHeaderCell width="10rem">Review</TableHeaderCell></TableHeaderRow>}>
      {packets.data.items.map(packet => <TableRow key={packet.id} rowKey={packet.id}><TableCell><div className="record-cell"><strong>{packet.changes.status.from} → {packet.changes.status.to}</strong><span>{timestamp(packet.created_at)}</span></div></TableCell><TableCell><Status value={packet.state === 'Consumed' ? 'Executed' : packet.state} /></TableCell><TableCell>{packet.requester.display_name}</TableCell><TableCell><Button onClick={() => setSelected(packet.id)}>Review packet</Button></TableCell></TableRow>)}
    </Table> : <Empty title="No approval requests" icon="task">Project status changes require an independently reviewed packet before execution.</Empty>}
    <Pagination next={packets.data?.next_cursor} total={packets.data?.total} page={pages.length + 1} previous={Boolean(pages.length)} onNext={() => { if (packets.data?.next_cursor) { setPages([...pages, cursor]); setCursor(packets.data.next_cursor); } }} onPrevious={() => { setCursor(pages[pages.length - 1]); setPages(pages.slice(0, -1)); }} />
    {requestOpen && <RequestStatus project={project} onClose={() => setRequestOpen(false)} onSourceChanged={onEffect} onRequested={packet => { setRequestOpen(false); setSelected(packet.id); setCursor(undefined); setPages([]); packets.refresh(); setNotice('Status change requested. The project has not changed.'); }} />}
    {selected && <ReviewPacket project={project} packetId={selected} onClose={() => setSelected(undefined)} onChanged={effect => { packets.refresh(); if (effect) onEffect(); }} />}
  </>;
}

function RequestStatus({ project, onClose, onRequested, onSourceChanged }: { project: Project; onClose: () => void; onSourceChanged: () => void; onRequested: (packet: ApprovalPacket) => void }) {
  const [status, setStatus] = useState(project.status === 'Open' ? 'On hold' : 'Open');
  const [operationId, setOperationId] = useState(() => crypto.randomUUID());
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<ApiError>();
  const submit = async () => {
    if (saving) return;
    setSaving(true); setError(undefined);
    try { const result = await api.requestStatus({ company: project.company, project: project.id, status, expected_version: project.version, operation_id: operationId }); onRequested(result.packet); }
    catch (failure) { setError(failure as ApiError); }
    finally { setSaving(false); }
  };
  return <Dialog open headerText="Request project status change" className="form-dialog" onClose={() => { if (!saving) onClose(); }} footer={<Bar design="Footer" endContent={<><Button design="Emphasized" disabled={saving || status === project.status} onClick={submit}>{saving ? 'Requesting…' : 'Submit approval request'}</Button><Button disabled={saving} onClick={onClose}>Cancel</Button></>} />}><div className="dialog-form">
    <p>{project.name}</p>{error && <><Failure error={error} />{error.status === 412 && <Button onClick={() => { onClose(); onSourceChanged(); }}>Refresh project before requesting again</Button>}</>}<Fact label="Current status"><Status value={project.status} /></Fact>
    <Label for="requested-project-status" required>Requested status</Label><Select id="requested-project-status" accessibleName="Requested project status" onChange={event => { setStatus(event.detail.selectedOption.value!); setOperationId(crypto.randomUUID()); setError(undefined); }}>{['Open', 'On hold', 'Completed', 'Cancelled'].map(value => <Option key={value} value={value} selected={status === value}>{value}</Option>)}</Select>
    <MessageStrip design="Information" hideCloseButton>This creates an approval packet. A different person must review it before an authorized person executes the change. Project tasks are not changed.</MessageStrip><p className="caption">The packet includes the resulting native completion percentage. Completed status requires all project tasks to be terminal. The server checks the source version and policy again at execution.</p>
  </div></Dialog>;
}

function ReviewPacket({ project, packetId, onClose, onChanged }: { project: Project; packetId: string; onClose: () => void; onChanged: (effect: boolean) => void }) {
  const resource = useResource(`${project.company}/${project.id}/${packetId}`, signal => api.approval(project.company, project.id, packetId, signal));
  const [reviewed, setReviewed] = useState(false);
  const [reason, setReason] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<ApiError>();
  const [notice, setNotice] = useState('');
  const operations = useRef(new Map<string, string>());
  const packet = resource.data;
  const act = async (action: 'Grant' | 'Reject' | 'execute' | 'withdraw') => {
    if (!packet || saving) return;
    const key = JSON.stringify([packet.id, packet.manifest_hash, action, action === 'execute' ? '' : reason.trim()]);
    if (!operations.current.has(key)) operations.current.set(key, crypto.randomUUID());
    setSaving(true); setError(undefined); setNotice('');
    try {
      await api.approvalAction(action, { company: project.company, project: project.id, packet_id: packet.id, manifest_hash: packet.manifest_hash, reason: reason.trim(), operation_id: operations.current.get(key)! });
      setReviewed(false); setReason(''); resource.refresh(); onChanged(action === 'execute');
      setNotice(action === 'execute' ? 'The approved status change was executed.' : action === 'Grant' ? 'Approval granted. Execution is a separate action.' : action === 'Reject' ? 'Approval request rejected.' : 'Approval request withdrawn.');
    } catch (failure) {
      const problem = failure as ApiError; setError(problem);
      if ([403, 404, 409, 412].includes(problem.status)) { setReviewed(false); resource.refresh(); }
    }
    finally { setSaving(false); }
  };
  return <Dialog open headerText="Review approval packet" className="approval-dialog" onClose={() => { if (!saving) onClose(); }} footer={<Bar design="Footer" endContent={<Button disabled={saving} onClick={onClose}>Close review</Button>} />}>
    {resource.loading ? <Loading label="Loading exact approval packet…" /> : resource.error ? <Failure error={resource.error} onRetry={resource.refresh} /> : packet && <div className="dialog-form">
      <div className="approval-heading"><Title level="H3">{packet.subject.label}</Title><Status value={packet.state === 'Consumed' ? 'Executed' : packet.state} /></div>
      {error && <Failure error={error} />}{notice && <MessageStrip design="Positive" hideCloseButton>{notice}</MessageStrip>}
      <div className="approval-change"><Fact label="Status at request">{packet.changes.status.from}</Fact><span aria-hidden="true">→</span><Fact label="Requested status">{packet.changes.status.to}</Fact></div>
      <dl className="approval-metadata"><dt>Requested by</dt><dd>{packet.requester.display_name}</dd><dt>Expires</dt><dd>{timestamp(packet.expires_at)}</dd><dt>Policy</dt><dd>{packet.policy.label}{packet.policy.synthetic ? ' · Synthetic' : ''}</dd><dt>Resulting completion</dt><dd>{packet.native_completion.percent_complete}% · {packet.native_completion.percent_complete_method || 'Task Completion'}</dd><dt>Tasks reviewed</dt><dd>{packet.task_effects.count}</dd><dt>Task changes</dt><dd>{packet.task_effects.changes.length ? `${packet.task_effects.changes.length} reported changes` : 'None — project status only'}</dd></dl>
      <details><summary>Packet integrity</summary><p className="caption">Packet {packet.id}</p><p className="caption">Source version: {packet.source_version}</p><code className="packet-hash">{packet.manifest_hash}</code></details>
      {packet.decisions.length > 0 && <div><Title level="H4">Decision history</Title><ol className="approval-decisions">{packet.decisions.map(decision => <li key={decision.id}><strong>{decision.decision}</strong> · {decision.actor.display_name}<span className="caption">{timestamp(decision.at)}</span>{decision.reason && <p>{decision.reason}</p>}</li>)}</ol></div>}
      {packet.actions.disabled_reason && <MessageStrip design="Information" hideCloseButton>{packet.actions.disabled_reason}</MessageStrip>}
      {(packet.actions.can_decide || packet.actions.can_execute || packet.actions.can_withdraw) && <>
        <Label for="approval-reason">Decision or withdrawal note (optional)</Label><TextArea id="approval-reason" accessibleName="Approval decision note" rows={2} value={reason} onInput={event => { setReason(event.currentTarget!.value); setError(undefined); }} />
        {(packet.actions.can_decide || packet.actions.can_execute) && <CheckBox text="I reviewed this exact change and its source" accessibleName="I reviewed this exact change and its source" checked={reviewed} onChange={event => setReviewed(event.currentTarget!.checked)} />}
        <div className="approval-actions">{packet.actions.can_decide && <><Button design="Emphasized" disabled={saving || !reviewed} onClick={() => act('Grant')}>Grant approval</Button><Button design="Negative" disabled={saving || !reviewed} onClick={() => act('Reject')}>Reject request</Button></>}{packet.actions.can_execute && <Button design="Emphasized" disabled={saving || !reviewed} onClick={() => act('execute')}>Execute approved change</Button>}{packet.actions.can_withdraw && <Button disabled={saving} onClick={() => act('withdraw')}>Withdraw request</Button>}</div>
      </>}
    </div>}
  </Dialog>;
}

import { useState } from 'react';
import { Table, TableHeaderRow, TableHeaderCell, TableRow, TableCell, Bar, Breadcrumbs, BreadcrumbsItem, Button, Dialog, Input, Label, Link, MessageStrip, ObjectPage, ObjectPageHeader, ObjectPageSection, ObjectPageTitle, TextArea, Title, Toolbar, ToolbarButton, ToolbarSpacer } from '@ui5/webcomponents-react';
import { api, ApiError } from './api/client';
import type { Project, Task } from './api/types';
