export default function ProjectDetail({ projectId, company, navigate, refreshProjects, onContext, openRicky }: {
  projectId: string; company: string; navigate: (path: string) => void; refreshProjects: () => void;
  onContext: (project: Project) => void; openRicky: () => void;
}) {
  const project = useResource(`${company}/${projectId}`, signal => api.project(company, projectId, signal));
  const [taskCursor, setTaskCursor] = useState<string>();
  const [taskPages, setTaskPages] = useState<(string | undefined)[]>([]);
  const [historyCursor, setHistoryCursor] = useState<string>();
  const [historyPages, setHistoryPages] = useState<(string | undefined)[]>([]);
  const tasks = useResource(`${company}/${projectId}/tasks/${taskCursor ?? ''}`, signal => api.tasks(company, projectId, signal, taskCursor));
  const history = useResource(`${company}/${projectId}/history/${historyCursor ?? ''}`, signal => api.history(company, projectId, signal, historyCursor));
  const documents = useResource(`${company}/${projectId}/documents`, signal => api.documents(company, projectId, signal));
  const [createOpen, setCreateOpen] = useState(false);
  const [notice, setNotice] = useState('');
  if (project.loading && !project.data) return <Loading label="Opening project workspace…" />;
  if (project.error) return <div className="page"><Failure error={project.error} onRetry={project.refresh} /></div>;
  if (!project.data) return null;
  const current = project.data;
  const refresh = () => { setTaskCursor(undefined); setTaskPages([]); setHistoryCursor(undefined); setHistoryPages([]); project.refresh(); tasks.refresh(); history.refresh(); documents.refresh(); refreshProjects(); };
  return <>
    <ObjectPage className="project-object-page" titleArea={<ObjectPageTitle
      header={<h1>{current.name}</h1>} subHeader={<span className="caption">{current.id} · {current.company}</span>}
      breadcrumbs={<Breadcrumbs><BreadcrumbsItem onClick={() => navigate('/projects')}>Projects</BreadcrumbsItem><BreadcrumbsItem>{current.name}</BreadcrumbsItem></Breadcrumbs>}
      actionsBar={<Toolbar design="Transparent"><ToolbarButton text="Ask Ricky" icon="da" onClick={() => { onContext(current); openRicky(); }} /><ToolbarButton text="Refresh" icon="refresh" onClick={refresh} /></Toolbar>}>
      <Status value={current.status} />
    </ObjectPageTitle>} headerArea={<ObjectPageHeader><div className="project-facts">
      <Fact label="Start date">{date(current.expected_start_date)}</Fact><Fact label="Target completion">{date(current.expected_end_date)}</Fact>
      <Fact label="Tasks">{tasks.data?.total ?? tasks.data?.items.length ?? '—'}</Fact><Fact label="Source documents">{documents.data?.items.length ?? '—'}</Fact>
    </div></ObjectPageHeader>}>
      <ObjectPageSection id="project-tasks" titleText="Tasks">
        <div className="section-body"><Toolbar design="Transparent"><Title level="H2">Project work</Title><ToolbarSpacer />{current.capabilities?.includes('task.create') && <Button icon="add" design="Emphasized" onClick={() => setCreateOpen(true)}>New task</Button>}</Toolbar>
          {notice && <MessageStrip design="Positive" onClose={() => setNotice('')}>{notice}</MessageStrip>}
          {tasks.loading ? <Loading label="Loading project tasks…" /> : tasks.error ? <Failure error={tasks.error} onRetry={tasks.refresh} /> : tasks.data?.items.length ? <Table accessibleName="Project tasks" overflowMode="Scroll" headerRow={<TableHeaderRow>
            <TableHeaderCell width="42%" minWidth="16rem">Task</TableHeaderCell><TableHeaderCell width="10rem">Status</TableHeaderCell><TableHeaderCell minWidth="15rem">Description</TableHeaderCell>
          </TableHeaderRow>}>
            {tasks.data.items.map(task => <TableRow key={task.id} rowKey={task.id}>
              <TableCell><div className="record-cell"><strong>{task.subject}</strong><span>{task.id}</span></div></TableCell>
              <TableCell><Status value={task.status} /></TableCell><TableCell><span>{task.description || 'No description'}</span></TableCell>
            </TableRow>)}
          </Table> : <Empty title="No tasks yet" icon="task">Create a task or ask Ricky to propose one from a project source.</Empty>}
          <Pagination next={tasks.data?.next_cursor} total={tasks.data?.total} page={taskPages.length + 1} previous={Boolean(taskPages.length)} onNext={() => { if (tasks.data?.next_cursor) { setTaskPages([...taskPages, taskCursor]); setTaskCursor(tasks.data.next_cursor); } }} onPrevious={() => { setTaskCursor(taskPages[taskPages.length - 1]); setTaskPages(taskPages.slice(0, -1)); }} />
        </div>
      </ObjectPageSection>
      <ObjectPageSection id="project-documents" titleText="Documents">
        <div className="section-body"><Toolbar design="Transparent"><Title level="H2">Source documents</Title><ToolbarSpacer /><Button icon="folder" onClick={() => navigate(`/projects/${encodeURIComponent(current.id)}/documents`)}>Manage documents</Button></Toolbar>
          {documents.loading ? <Loading label="Loading source documents…" /> : documents.error ? <Failure error={documents.error} onRetry={documents.refresh} /> : <DocumentRegister items={documents.data?.items ?? []} navigate={navigate} />}
        </div>
      </ObjectPageSection>
      <ObjectPageSection id="project-approvals" titleText="Approvals">
        <div className="section-body"><Approvals project={current} onEffect={refresh} /></div>
      </ObjectPageSection>
      <ObjectPageSection id="project-history" titleText="Activity">
        <div className="section-body history-section"><Title level="H2">Project activity</Title>
          {history.loading ? <Loading label="Loading project history…" /> : history.error ? <Failure error={history.error} onRetry={history.refresh} /> : history.data?.items.length ? <ol className="activity-list">{history.data.items.map(item => <li key={item.id}><span className="activity-dot" /><div><strong>{human(item.event)}</strong><p>{item.actor} · {date(item.at)}</p><span className="caption">{item.subject_type}: {item.subject_id}</span></div></li>)}</ol> : <Empty title="No recorded activity" icon="history">Activity from saved project changes will appear here.</Empty>}
          <Pagination next={history.data?.next_cursor} total={history.data?.total} page={historyPages.length + 1} previous={Boolean(historyPages.length)} onNext={() => { if (history.data?.next_cursor) { setHistoryPages([...historyPages, historyCursor]); setHistoryCursor(history.data.next_cursor); } }} onPrevious={() => { setHistoryCursor(historyPages[historyPages.length - 1]); setHistoryPages(historyPages.slice(0, -1)); }} />
        </div>
      </ObjectPageSection>
    </ObjectPage>
    <TaskDialog open={createOpen} project={current} onClose={() => setCreateOpen(false)} onSaved={task => { setNotice(`Task “${task.subject}” was created.`); setCreateOpen(false); refresh(); }} />
  </>;
}

function TaskDialog({ open, project, onClose, onSaved }: { open: boolean; project: Project; onClose: () => void; onSaved: (task: Task) => void }) {
  const [subject, setSubject] = useState('');
  const [description, setDescription] = useState('');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<ApiError>();
  const [operationId, setOperationId] = useState(() => crypto.randomUUID());
  const save = async () => {
    if (!subject.trim() || saving) return;
    setSaving(true); setError(undefined);
    try {
      const result = await api.createTask({ company: project.company, project: project.id, expected_version: project.version, operation_id: operationId, subject: subject.trim(), description: description.trim() });
      setSubject(''); setDescription(''); setOperationId(crypto.randomUUID()); onSaved(result.task);
    } catch (failure) { setError(failure as ApiError); }
    finally { setSaving(false); }
  };
  const change = () => { setOperationId(crypto.randomUUID()); setError(undefined); };
  return <Dialog open={open} headerText="Create project task" onClose={() => { if (!saving) onClose(); }} className="form-dialog" footer={<Bar design="Footer" endContent={<><Button design="Emphasized" disabled={!subject.trim() || saving} onClick={save}>{saving ? 'Saving…' : 'Create task'}</Button><Button disabled={saving} onClick={onClose}>Cancel</Button></>} />}>
    <div className="dialog-form"><p className="caption">{project.name}</p>{error && <Failure error={error} />}
      <Label for="task-subject" required>Task name</Label><Input id="task-subject" accessibleName="Task name" value={subject} maxlength={140} onInput={event => { setSubject(event.currentTarget!.value); change(); }} />
      <Label for="task-description">Description</Label><TextArea id="task-description" accessibleName="Task description" value={description} rows={4} onInput={event => { setDescription(event.currentTarget!.value); change(); }} />
    </div>
  </Dialog>;
}

import { useEffect, useRef, useState } from 'react';
import { Button, CheckBox, Icon, Link, MessageStrip, TextArea, Title } from '@ui5/webcomponents-react';
import type { TextAreaDomRef } from '@ui5/webcomponents-react';
import { ApiError, rpc } from './api/client';
import type { Citation, ModelStatus, Project, RickyProposal, RickyRun } from './api/types';
import { human, useResource } from './hooks';
import { Empty, Failure, Loading, Status } from './components';

const prefix = 'cipher_aec.ricky.api.';
const terminal = new Set(['succeeded', 'failed', 'cancelled', 'waiting_for_review', 'waiting-for-review', 'completed']);

export default function RickyPanel({ company, project, person, navigate, onClose, onSaved }: { company: string; project?: Project; person: string; navigate: (path: string) => void; onClose: () => void; onSaved: () => void }) {
  const connection = useResource('ricky/connection', signal => rpc<ModelStatus>(`${prefix}connection_status`, {}, false, signal));
  const storageKey = `cipher.run.${person}.${company}.${project?.id ?? ''}`;
  const [runId, setRunId] = useState<string | null>(() => sessionStorage.getItem(storageKey));
  const [run, setRun] = useState<RickyRun>();
  const [question, setQuestion] = useState('');
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<ApiError>();
  const [operationId, setOperationId] = useState(() => crypto.randomUUID());
  const [notice, setNotice] = useState('');
  const inputRef = useRef<TextAreaDomRef>(null);
  useEffect(() => {
    if (!runId) return;
    const controller = new AbortController(); let timer: ReturnType<typeof setTimeout>;
    const poll = async () => {
      try {
        const next = await rpc<RickyRun>(`${prefix}get_run`, { run_id: runId }, false, controller.signal);
        if (controller.signal.aborted) return;
        setRun(next); setError(undefined);
        if (!terminal.has(next.status)) timer = setTimeout(poll, 1800);
      } catch (failure) { if (!controller.signal.aborted) { setError(failure as ApiError); if (failure instanceof ApiError && [401, 403, 404].includes(failure.status)) { setRun(undefined); sessionStorage.removeItem(storageKey); } } }
    };
    void poll();
    return () => { controller.abort(); clearTimeout(timer); };
  }, [runId]);
  const ask = async () => {
    if (!project || !question.trim() || sending) return;
    setSending(true); setError(undefined);
    try {
      const next = await rpc<RickyRun>(`${prefix}start_run`, { company, project: project.id, question: question.trim(), operation_id: operationId }, true);
      setRun(next); setRunId(next.id); sessionStorage.setItem(storageKey, next.id);
    } catch (failure) { setError(failure as ApiError); }
    finally { setSending(false); }
  };
  const cancel = async () => {
    if (!run) return;
    setSending(true);
    try { setRun(await rpc<RickyRun>(`${prefix}cancel_run`, { run_id: run.id, operation_id: crypto.randomUUID() }, true)); }
    catch (failure) { setError(failure as ApiError); }
    finally { setSending(false); }
  };
  const reset = () => { setRun(undefined); setRunId(null); setError(undefined); setNotice(''); setQuestion(''); setOperationId(crypto.randomUUID()); sessionStorage.removeItem(storageKey); setTimeout(() => inputRef.current?.focus(), 0); };
  return <aside className="ricky-panel" aria-label="Ricky project assistant">
    <header className="ricky-header"><div className="ricky-identity"><div className="ricky-mark"><Icon name="da" /></div><div><Title level="H2">Ricky</Title><span>AEC intelligence</span></div></div><Button icon="decline" design="Transparent" accessibleName="Close Ricky" onClick={onClose} /></header>
    <div className="ricky-context"><Icon name="folder" /><div><span>PROJECT CONTEXT</span><strong>{project?.name ?? 'No project selected'}</strong></div></div>
    <div className="ricky-scroll">
      {connection.loading ? <Loading label="Checking local model…" /> : connection.error ? <Failure error={connection.error} onRetry={connection.refresh} /> : connection.data && !connection.data.available ? <div className="model-unavailable"><Icon name="disconnected" /><h3>Ricky is not connected</h3><p>{connection.data.message || 'The existing local model connection has not been configured for this workspace.'}</p><Button icon="refresh" onClick={connection.refresh}>Check connection</Button><p className="caption">Your project, tasks and documents are still available.</p></div> : <div className="model-state"><span className="state-dot" />{connection.data?.adapter_kind?.includes('fixture') ? 'Synthetic model test adapter' : 'Local model available'}</div>}
      {!project ? <Empty title="Start with a project" icon="folder" action={<Button onClick={() => navigate('/projects')}>Open projects</Button>}>Ricky uses the same project and document access as you.</Empty> : <>
        {notice && <MessageStrip design="Positive" onClose={() => setNotice('')}>{notice}</MessageStrip>}
        {!run && !runId && connection.data?.available && <div className="ricky-intro"><h3>Work from the source.</h3><p>Ask about this project, find supporting evidence, or draft the next task.</p><div className="prompt-list">{['Summarize the available project sources.', 'What needs follow-up in the project documents?', 'Propose a task from the source requirements.'].map(prompt => <button key={prompt} className="prompt-button" onClick={() => { setQuestion(prompt); setOperationId(crypto.randomUUID()); inputRef.current?.focus(); }}>{prompt}<Icon name="navigation-right-arrow" /></button>)}</div></div>}
        {error && <Failure error={error} />}
        {runId && !run && !error && <Loading label="Loading saved run…" />}
        {run && <div className="run-content"><div className="question-bubble">{run.question}</div><div className="run-status"><Status value={run.status} /><span className="caption">Saved run</span></div>
          {!terminal.has(run.status) && <div className="run-progress" role="status"><span className="pulse-dot" />{run.cancel_requested ? 'Cancellation requested…' : `${human(run.status)}…`}<Button design="Transparent" disabled={sending || run.cancel_requested} onClick={cancel}>Cancel</Button></div>}
          {run.answer && <div className="answer-text">{run.answer}</div>}
          {run.error && <MessageStrip design="Negative" hideCloseButton>{run.error.message || 'This request could not be completed.'}</MessageStrip>}
          {run.citations?.length > 0 && <div className="citation-list"><h4>Sources</h4>{run.citations.map((citation, index) => <CitationLink key={`${citation.revision_id}-${index}`} citation={citation} navigate={navigate} />)}</div>}
          {run.proposal_ids?.map(id => <ProposalCard key={id} id={id} onSaved={taskName => { setNotice(`Task “${taskName}” was created.`); onSaved(); }} navigate={navigate} />)}
          {terminal.has(run.status) && <Button design="Transparent" icon="add" onClick={reset}>New request</Button>}
        </div>}
      </>}
    </div>
    <div className="ricky-composer"><TextArea ref={inputRef} accessibleName="Ask Ricky about this project" placeholder={project ? 'Ask about this project…' : 'Select a project to begin…'} value={question} rows={3} disabled={!project || !connection.data?.available || Boolean(runId) || sending} onInput={event => { setQuestion(event.currentTarget!.value); setOperationId(crypto.randomUUID()); }} />
      <div className="composer-actions"><span>Sources first. You review changes.</span><Button icon="paper-plane" design="Emphasized" disabled={!question.trim() || !project || !connection.data?.available || Boolean(runId) || sending} onClick={ask} accessibleName="Send question to Ricky">{sending && !run ? 'Sending…' : 'Send'}</Button></div>
    </div>
  </aside>;
}

function ProposalCard({ id, navigate, onSaved }: { id: string; navigate: (path: string) => void; onSaved: (name: string) => void }) {
  const proposal = useResource(id, signal => rpc<RickyProposal>(`${prefix}get_proposal`, { proposal_id: id }, false, signal));
  const [reviewed, setReviewed] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const [error, setError] = useState<ApiError>();
  const [operationId] = useState(() => crypto.randomUUID());
  if (proposal.loading) return <Loading label="Loading proposed task…" />;
  if (proposal.error) return <Failure error={proposal.error} onRetry={proposal.refresh} />;
  if (!proposal.data) return null;
  const current = proposal.data;
  const commit = async () => {
    if (!reviewed || saving) return;
    setSaving(true); setError(undefined);
    try { await rpc(`${prefix}commit_proposal`, { proposal_id: current.id, proposal_version: current.version, operation_id: operationId }, true); setSaved(true); onSaved(current.fields.subject); }
    catch (failure) { setError(failure as ApiError); }
    finally { setSaving(false); }
  };
  return <section className="proposal-card" aria-label="Proposed task"><div className="proposal-heading"><Icon name="task" /><strong>Proposed task</strong><Status value={saved ? 'saved' : current.status} /></div>
    <h4>{current.fields.subject}</h4>{current.fields.description && <p>{current.fields.description}</p>}
    {current.sources?.map((source, index) => <CitationLink key={`${source.revision_id}-${index}`} citation={source} navigate={navigate} />)}
    {error && <Failure error={error} />}
    {!saved && !['committed', 'applied', 'expired', 'cancelled', 'rejected'].includes(current.status) && <><CheckBox checked={reviewed} onChange={event => setReviewed(event.currentTarget!.checked)} text="I reviewed this task and its sources" /><Button design="Emphasized" disabled={!reviewed || saving} onClick={commit}>{saving ? 'Saving…' : 'Create proposed task'}</Button></>}
    {saved && <p className="caption">Saved to this project. No other action was performed.</p>}
  </section>;
}

function CitationLink({ citation, navigate }: { citation: Citation; navigate: (path: string) => void }) {
  return <div className="citation"><Icon name="document-text" /><div><Link onClick={() => navigate(`/documents/${encodeURIComponent(citation.document_id)}/revisions/${encodeURIComponent(citation.revision_id)}?page=${citation.page}`)}>{citation.document_title || 'Source document'}</Link><span>Rev. {citation.revision_number} · {citation.page_label || `Page ${citation.page}`}</span>{citation.excerpt && <p>{citation.excerpt}</p>}</div></div>;
}

import { useState } from 'react';
import { Button, Icon, Input, Label } from '@ui5/webcomponents-react';
import { api, ApiError } from './api/client';
import { Failure } from './components';

export default function SignIn({ onSignedIn }: { onSignedIn: () => void }) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<ApiError>();
  const submit = async () => {
    if (!username.trim() || !password || busy) return;
    setBusy(true); setError(undefined);
    try { await api.signIn(username.trim(), password); setPassword(''); onSignedIn(); }
    catch (failure) { setError(failure as ApiError); }
    finally { setBusy(false); }
  };
  return <div className="sign-in-page"><section className="sign-in-card" aria-labelledby="sign-in-title"><div className="sign-in-brand"><img src="/cipher-mark.svg" alt="" /><span>Cipher</span></div><span className="eyebrow">THE AEC/CMS PRO</span><h1 id="sign-in-title">Sign in to your workspace</h1><p>Projects, source documents and the next step. Together in one place.</p>
    <form onSubmit={event => { event.preventDefault(); void submit(); }}>
      {error && <Failure error={error} />}
      <Label for="sign-in-user" required>Email or username</Label><Input id="sign-in-user" accessibleName="Email or username" name="username" value={username} disabled={busy} onInput={event => setUsername(event.currentTarget!.value)} />
      <Label for="sign-in-password" required>Password</Label><Input id="sign-in-password" accessibleName="Password" type="Password" name="password" value={password} disabled={busy} onInput={event => setPassword(event.currentTarget!.value)} />
      <Button design="Emphasized" type="Submit" disabled={busy || !username.trim() || !password}>{busy ? 'Signing in…' : 'Sign in'}</Button>
    </form><div className="sign-in-footnote"><Icon name="locked" /><span>Your account controls access to companies, projects and documents.</span></div>
  </section></div>;
}

import { useEffect, useRef, useState } from 'react';
import { Avatar, Bar, Button, Dialog, Icon, Link, MessageStrip, NavigationLayout, Option, Select, ShellBar, ShellBarBranding, ShellBarSearch, ShellBarSpacer, SideNavigation, SideNavigationItem, Tag, Title, ToggleButton, Toolbar, ToolbarSpacer } from '@ui5/webcomponents-react';
import type { NavigationLayoutDomRef } from '@ui5/webcomponents-react';
import NavigationLayoutMode from '@ui5/webcomponents-fiori/dist/types/NavigationLayoutMode.js';
import { api, ApiError, rpc } from './api/client';
import type { ModelStatus, Project, Session } from './api/types';
import { useResource, useRoute } from './hooks';
import { Empty, Failure, Loading, PageHeading, Status } from './components';
import ProjectRegister from './ProjectRegister';
import ProjectDetail from './ProjectDetail';
import { DocumentPage, DocumentsPage } from './Documents';
import RickyPanel from './RickyPanel';
import SignIn from './SignIn';
import Approvals from './Approvals';

export default function App() {
  const { path, navigate } = useRoute();
  const session = useResource('session', signal => api.session(signal));
  const [company, setCompany] = useState('');
  const [projectId, setProjectId] = useState('');
  const [rickyOpen, setRickyOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [mode, setMode] = useState<NavigationLayoutMode>(NavigationLayoutMode.Auto);
  const [search, setSearch] = useState('');
  const [dataRevision, setDataRevision] = useState(0);
  const [authRequested, setAuthRequested] = useState(false);
  const [signingOut, setSigningOut] = useState(false);
  const [profileError, setProfileError] = useState<ApiError>();
  const [projectCursor, setProjectCursor] = useState<string>();
  const [projectPages, setProjectPages] = useState<(string | undefined)[]>([]);
  const layoutRef = useRef<NavigationLayoutDomRef>(null);
  const identity = session.data?.person.id ?? '';
  const projects = useResource(company && identity ? `projects/${identity}/${company}/${projectCursor ?? ''}` : null, signal => api.projects(company, signal, projectCursor));
  const route = path.split('?')[0].split('/').filter(Boolean).map(segment => { try { return decodeURIComponent(segment); } catch { return segment; } });
  const citedPage = Number(new URLSearchParams(path.split('?')[1] ?? '').get('page'));
  const routeProjectId = route[0] === 'projects' ? route[1] : undefined;
  const contextId = routeProjectId || projectId;
  const contextProject = useResource(company && contextId && identity ? `project-context/${identity}/${company}/${contextId}` : null, signal => api.project(company, contextId!, signal));
  const selectedProject = contextProject.data ?? projects.data?.items.find(project => project.id === contextId);

  useEffect(() => {
    const currentSession = session.data;
    if (currentSession) setCompany(current => currentSession.companies.some(item => item.id === current) ? current : currentSession.companies[0]?.id ?? '');
  }, [session.data]);
  useEffect(() => { setProjectId(''); setProjectCursor(undefined); setProjectPages([]); setRickyOpen(false); }, [session.data?.user]);
  useEffect(() => {
    const signIn = () => { setAuthRequested(true); setRickyOpen(false); };
    const expired = () => { setAuthRequested(true); setRickyOpen(false); setProfileOpen(false); setProjectId(''); };
    window.addEventListener('cipher:sign-in', signIn); window.addEventListener('cipher:session-expired', expired);
    return () => { window.removeEventListener('cipher:sign-in', signIn); window.removeEventListener('cipher:session-expired', expired); };
  }, []);
  useEffect(() => { if (routeProjectId) setProjectId(routeProjectId); }, [routeProjectId]);
  useEffect(() => { document.title = `${selectedProject?.name ?? (route[0] === 'documents' ? 'Document' : route[0] === 'connections' ? 'Connections' : 'Projects')} · Cipher`; }, [selectedProject?.name, path]);

  const changeCompany = (next: string) => { setCompany(next); setProjectId(''); setSearch(''); setProjectCursor(undefined); setProjectPages([]); navigate('/projects'); };
  const refresh = () => { projects.refresh(); contextProject.refresh(); setDataRevision(value => value + 1); };
  const toggleNavigation = () => setMode(layoutRef.current?.isSideCollapsed() ? NavigationLayoutMode.Expanded : NavigationLayoutMode.Collapsed);
  const documentsPath = selectedProject ? `/projects/${encodeURIComponent(selectedProject.id)}/documents` : '/documents';
  const shellSession = !authRequested && !session.error && session.data?.authenticated ? session.data : undefined;
  const personName = shellSession?.person.display_name ?? 'Workspace session';
  const navKey = route[0] === 'documents' || route[2] === 'documents' ? 'documents' : route[0] === 'work' ? 'work' : route[0] === 'connections' ? 'connections' : 'projects';
  return <>
    <a className="skip-link" href="#main-content">Skip to content</a>
    <NavigationLayout ref={layoutRef} id="cipher-navigation" mode={mode} className="product-layout"
      header={<ShellBar id="cipher-shellbar" startButton={<Button icon="menu2" design="Transparent" accessibleName="Toggle navigation" onClick={toggleNavigation} />}
        branding={<ShellBarBranding logo={<img src="/cipher-mark.svg" alt="" />} onClick={() => navigate('/projects')}>Cipher <span className="shell-product-subtitle">The AEC/CMS Pro</span></ShellBarBranding>}
        content={<><div className="company-switch">{shellSession?.companies.length ? <Select accessibleName="Company" valueState="None" onChange={event => changeCompany(event.detail.selectedOption.value ?? company)}>{shellSession.companies.map(item => <Option key={item.id} value={item.id} selected={company === item.id}>{item.name}</Option>)}</Select> : null}</div><ShellBarSpacer />{shellSession?.site_mode === 'synthetic' && <Tag design="Set2" colorScheme="7">Synthetic workspace</Tag>}</>}
        searchField={<ShellBarSearch placeholder="Find a project" accessibleName="Search projects" onSearch={event => { setSearch(event.currentTarget!.value); navigate('/projects'); }} />}
        assistant={<ToggleButton icon="da" pressed={rickyOpen} accessibleName="Toggle Ricky assistant" tooltip="Ricky · AEC intelligence" onClick={() => setRickyOpen(value => !value)} />}
        profile={<Avatar initials={initials(personName)} accessibleName={personName} size="XS" />} onProfileClick={() => { if (shellSession) setProfileOpen(true); }} />}
      sideContent={<SideNavigation className="product-navigation" accessibleName="Cipher workspace navigation" onSelectionChange={event => { const next = event.detail.item.dataset.path; if (next) navigate(next); }} fixedItems={<SideNavigationItem text="Connections" icon="connected" selected={navKey === 'connections'} data-path="/connections" />}>
        <SideNavigationItem text="Projects" icon="building" selected={navKey === 'projects'} data-path="/projects" />
        <SideNavigationItem text="Project work" icon="task" selected={navKey === 'work'} data-path="/work" />
        <SideNavigationItem text="Documents" icon="documents" selected={navKey === 'documents'} data-path={documentsPath} />
        <SideNavigationItem text="Ricky" icon="da" design="Action" unselectable onClick={() => setRickyOpen(true)} />
      </SideNavigation>}>
      <div className={`workspace-frame${rickyOpen ? ' with-assistant' : ''}`}>
        <div className="workspace-main" id="main-content" tabIndex={-1}>
          {session.loading ? <Loading label="Connecting to your workspace…" /> : authRequested || session.error?.status === 401 || (!session.error && !session.data?.authenticated) ? <SignIn onSignedIn={() => { setAuthRequested(false); session.refresh(); }} /> : session.error ? <WorkspaceUnavailable error={session.error} retry={session.refresh} /> : !session.data?.companies.length ? <div className="page"><Empty title="No company access" icon="locked">Your workspace administrator can assign company and project access.</Empty></div> : <>
            <div className="workspace-context-bar"><div><Icon name="building" /><span>{companyLabel(session.data, company)}</span>{selectedProject && <><span className="context-separator">/</span><strong>{selectedProject.name}</strong></>}</div><Select accessibleName="Project context" onChange={event => { const id = event.detail.selectedOption.value ?? ''; setProjectId(id); navigate(id ? `/projects/${encodeURIComponent(id)}` : '/projects'); }}><Option value="" selected={!selectedProject}>All projects</Option>{projects.data?.items.map(project => <Option key={project.id} value={project.id} selected={selectedProject?.id === project.id}>{project.name}</Option>)}</Select></div>
            {projects.loading && !projects.data ? <Loading label="Loading permitted projects…" /> : projects.error ? <div className="page"><Failure error={projects.error} onRetry={projects.refresh} /></div> : company && <>
              {route[0] === 'connections' ? <Connections session={session.data} />
                : route[0] === 'documents' && route[1] ? <DocumentPage key={`${company}/${path}`} company={company} documentId={route[1]} revisionId={route[2] === 'revisions' ? route[3] : undefined} initialPage={Number.isInteger(citedPage) && citedPage > 0 ? citedPage : 1} navigate={navigate} askRicky={id => { setProjectId(id); setRickyOpen(true); }} />
                : route[0] === 'documents' || route[2] === 'documents' ? <DocumentsPage key={`${company}/${selectedProject?.id ?? ''}`} company={company} projectId={selectedProject?.id} projectName={selectedProject?.name} navigate={navigate} canUpload={contextProject.data?.capabilities?.includes('document.write') ?? false} />
                : route[0] === 'work' ? <WorkPage key={`${company}/${selectedProject?.id}/${dataRevision}`} company={company} project={selectedProject} navigate={navigate} onEffect={() => { projects.refresh(); contextProject.refresh(); }} />
                : route[0] === 'projects' && routeProjectId ? <ProjectDetail key={`${company}/${routeProjectId}/${dataRevision}`} company={company} projectId={routeProjectId} navigate={navigate} refreshProjects={projects.refresh} onContext={project => setProjectId(project.id)} openRicky={() => setRickyOpen(true)} />
                : <ProjectRegister company={companyLabel(session.data, company)} projects={projects.data?.items ?? []} total={projects.data?.total ?? undefined} search={search} setSearch={setSearch} navigate={navigate} refresh={projects.refresh} pagination={{ next: projects.data?.next_cursor, page: projectPages.length + 1, previous: Boolean(projectPages.length), onNext: () => { if (projects.data?.next_cursor) { setProjectPages([...projectPages, projectCursor]); setProjectCursor(projects.data.next_cursor); } }, onPrevious: () => { setProjectCursor(projectPages[projectPages.length - 1]); setProjectPages(projectPages.slice(0, -1)); } }} />}
            </>}
          </>}
        </div>
        {rickyOpen && !session.loading && !authRequested && session.data?.authenticated && <RickyPanel key={`${session.data.person.id}/${company}/${selectedProject?.id ?? ''}`} company={company} person={session.data.person.id} project={selectedProject} navigate={navigate} onClose={() => setRickyOpen(false)} onSaved={refresh} />}
      </div>
    </NavigationLayout>
    <Dialog open={profileOpen} headerText="Your workspace session" onClose={() => setProfileOpen(false)} footer={<Bar design="Footer" endContent={<><Button disabled={signingOut} onClick={async () => { setSigningOut(true); setProfileError(undefined); try { await api.signOut(); setProfileOpen(false); setAuthRequested(true); setRickyOpen(false); session.refresh(); } catch (error) { setProfileError(error as ApiError); } finally { setSigningOut(false); } }}>{signingOut ? 'Signing out…' : 'Sign out'}</Button><Button onClick={() => setProfileOpen(false)}>Close</Button></>} />}><div className="dialog-form">{profileError && <Failure error={profileError} />}<div className="profile-summary"><Avatar initials={initials(personName)} /><div><Title level="H3">{personName}</Title><p>{session.data?.user ?? 'Not signed in'}</p></div></div><p>Company and project permissions are supplied by your workspace.</p>{session.data?.site_mode === 'synthetic' && <MessageStrip design="Information" hideCloseButton>This workspace contains synthetic data.</MessageStrip>}</div></Dialog>
  </>;
}

function WorkspaceUnavailable({ error, retry }: { error: import('./api/client').ApiError; retry: () => void }) {
  return <div className="page connection-page"><div className="connection-illustration"><Icon name="disconnected" /></div><PageHeading eyebrow="CIPHER WORKSPACE" title={error.status === 401 ? 'Sign in to continue' : 'Your workspace is unavailable'} description="Your project data is loaded from your authenticated workspace." /><Failure error={error} onRetry={retry} /><p className="caption">This application does not substitute sample records when a connection fails.</p></div>;
}

function WorkPage({ company, project, navigate, onEffect }: { company: string; project?: Project; navigate: (path: string) => void; onEffect: () => void }) {
  const tasks = useResource(project ? `${company}/${project.id}/tasks` : null, signal => api.tasks(company, project!.id, signal));
  return <div className="page"><PageHeading eyebrow="PROJECT DELIVERY" title="Project work" description={project ? `Tasks, approvals and follow-up for ${project.name}.` : 'Choose a project to see its work.'} />
    {!project ? <div className="surface"><Empty title="Choose a project" icon="task" action={<Button design="Emphasized" onClick={() => navigate('/projects')}>Open projects</Button>}>Select a project from the context picker or project register.</Empty></div> : tasks.loading ? <Loading label="Loading tasks…" /> : tasks.error ? <Failure error={tasks.error} onRetry={tasks.refresh} /> : <section className="surface work-list"><Toolbar design="Transparent"><Title level="H2">Project tasks ({tasks.data?.items.length ?? 0})</Title><ToolbarSpacer /><Button onClick={() => navigate(`/projects/${encodeURIComponent(project.id)}`)}>Open project</Button></Toolbar>{tasks.data?.items.length ? tasks.data.items.map(task => <div className="work-item" key={task.id}><Icon name="task" /><div><strong>{task.subject}</strong><p>{task.description || task.id}</p></div><Status value={task.status} /></div>) : <Empty title="No tasks yet" icon="task">Create the first task from your project workspace.</Empty>}</section>}
    {project && <section className="surface work-approvals"><Approvals project={project} onEffect={onEffect} /></section>}
  </div>;
}

function Connections({ session }: { session: Session }) {
  const model = useResource('connections/model', signal => rpc<ModelStatus>('cipher_aec.ricky.api.connection_status', {}, false, signal));
  return <div className="page"><PageHeading eyebrow="WORKSPACE" title="Connections" description="Current availability of the services behind your work." actions={<Button icon="refresh" onClick={model.refresh}>Refresh</Button>} />
    <section className="surface connection-list"><div className="connection-item"><div className="connection-icon"><Icon name="database" /></div><div><h2>ERP workspace</h2><p>Authenticated business records, projects and tasks.</p></div><Status value="Connected" /></div><div className="connection-item"><div className="connection-icon"><Icon name="da" /></div><div><h2>Ricky local model</h2><p>{model.data?.message || 'The existing local model connection.'}</p></div>{model.loading ? <span className="caption">Checking…</span> : <Status value={model.data?.available ? 'Connected' : 'Unavailable'} />}</div>{model.error && <Failure error={model.error} onRetry={model.refresh} />}</section>
    <div className="document-policy"><strong>{session.site_mode === 'synthetic' ? 'Synthetic workspace' : 'Workspace access'}</strong><p>Connected records use your current company and project permissions. Ricky availability does not affect manual project work.</p></div>
  </div>;
}

function initials(name: string) { return name.split(/[\s@.]+/).filter(Boolean).slice(0, 2).map(part => part[0]?.toUpperCase()).join('') || 'C'; }
function companyLabel(session: Session, company: string) { return session.companies.find(item => item.id === company)?.name ?? company; }

